#!/usr/bin/env python3
"""Offline build with the already pinned Hike/WABT toolchain."""
import hashlib,json,os,subprocess
from pathlib import Path
r=Path(__file__).resolve().parent
t=Path(os.environ.get('DIFFUSION_TOOLCHAIN',str(r.parents[1]/'toolchain'))).resolve()
out=r/'build';out.mkdir(exist_ok=True)
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
pin=json.loads((t/'provenance.json').read_text());compiler=t/'hikec'
assert sha(compiler)==pin['sha256']['compiler']
env=dict(os.environ,PATH=str(t/'wabt/node_modules/.bin')+os.pathsep+os.environ['PATH'])
command=[str(compiler),'build','-target','wabt','-wasm-mode','normal','-o',str(out/'generated-space.wasm'),str(r/'generated-space.hike')]
p=subprocess.run(command,env=env,capture_output=True,text=True);(out/'compiler.log').write_text(p.stdout+p.stderr);p.check_returncode()
subprocess.run(['node',str(t/'wabt/node_modules/wabt/bin/wasm2wat'),str(out/'generated-space.wasm'),'-o',str(out/'generated-space.wat')],check=True)
assert '(import ' not in (out/'generated-space.wat').read_text()
result={'abi':'wan21-generated-space-chunk-f32-v2','hikeCommit':pin['hikeCommit'],'compilerSha256':sha(compiler),'builderSha256':sha(r/'build.py'),'hostSha256':sha(r.parent/'generated-space.mjs'),'sourceSha256':sha(r/'generated-space.hike'),'wasmSha256':sha(out/'generated-space.wasm'),'watSha256':sha(out/'generated-space.wat'),'generatedRuntimeSha256':sha(out/'runtime.js'),'runtimeUsed':False,'versions':pin['versions'],'backend':'wabt normal','command':command,'imports':[],'chunkElements':4096,'maxElements':4194304,'arenaBytes':32768,'scope':'Generated sample process_out, distinct HIGH/LOW handoff process_out/in, and context raw-mean process_in; no model inference or sampling'}
(out/'build-record.json').write_text(json.dumps(result,indent=2)+'\n')
(r/'kernel-registry.mjs').write_text('// Generated by offline build.py from real Hike output.\nexport const GENERATED_SPACE_KERNEL=Object.freeze('+json.dumps({'abi':result['abi'],'sha256':result['wasmSha256'],'sourceSha256':result['sourceSha256']},separators=(',',':'))[:-1]+',url:new URL("./build/generated-space.wasm",import.meta.url).href});\n')
print(json.dumps(result))
